import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-07-27/navfn_core_01_overview.png",p="/Nav2ArticlesSite/article-assets/2026-07-27/navfn_core_02_costmap.png",i="/Nav2ArticlesSite/article-assets/2026-07-27/navfn_core_03_direction.png",l="/Nav2ArticlesSite/article-assets/2026-07-27/navfn_core_04_wave_update.png",c="/Nav2ArticlesSite/article-assets/2026-07-27/navfn_core_05_astar_dijkstra.png",d="/Nav2ArticlesSite/article-assets/2026-07-27/navfn_core_06_extract_output.png",_=JSON.parse('{"title":"从机器人脚下掀起一场“势能洪水”：Nav2 NavFn 如何把 Costmap 变成路径？","description":"给 NavFn 一张 Costmap、一个机器人位置和一个目标点，它不会直接在栅格里保存一串父节点，也不会先得到折线路径再调用独立平滑器。","frontmatter":{"title":"从机器人脚下掀起一场“势能洪水”：Nav2 NavFn 如何把 Costmap 变成路径？","description":"给 NavFn 一张 Costmap、一个机器人位置和一个目标点，它不会直接在栅格里保存一串父节点，也不会先得到折线路径再调用独立平滑器。","date":"2026-07-27","section":"二 · 全局规划与路径搜索","readingTime":17,"source":"2026-07-27/nav2_navfn_planner_core_algorithm.md","status":"published","cover":"/article-assets/2026-07-27/navfn_core_01_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-navfn-planner-core-algorithm"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"从机器人脚下掀起一场“势能洪水”：Nav2 NavFn 如何把 Costmap 变成路径？"}],["meta",{"property":"og:description","content":"给 NavFn 一张 Costmap、一个机器人位置和一个目标点，它不会直接在栅格里保存一串父节点，也不会先得到折线路径再调用独立平滑器。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-navfn-planner-core-algorithm"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-27/navfn_core_01_overview.png"}],["meta",{"property":"article:published_time","content":"2026-07-27"}],["meta",{"name":"twitter:title","content":"从机器人脚下掀起一场“势能洪水”：Nav2 NavFn 如何把 Costmap 变成路径？"}],["meta",{"name":"twitter:description","content":"给 NavFn 一张 Costmap、一个机器人位置和一个目标点，它不会直接在栅格里保存一串父节点，也不会先得到折线路径再调用独立平滑器。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-27/navfn_core_01_overview.png"}]],"prev":{"text":"一个目标点要闯过多少关？逐函数拆解 Nav2 Planner Server 的 21 段数据流","link":"/nav2/nav2-planner-source-walkthrough"},"next":{"text":"A* 不只会“走格子”：Nav2 Smac Planner 如何把转弯半径、倒车与避障写进搜索？","link":"/nav2/nav2-smac-planner-core-algorithm"}},"headers":[],"relativePath":"nav2/nav2-navfn-planner-core-algorithm.md","filePath":"nav2/nav2-navfn-planner-core-algorithm.md","lastUpdated":null}'),r={name:"nav2/nav2-navfn-planner-core-algorithm.md"};function h(u,a,g,b,v,k){return s(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="从机器人脚下掀起一场-势能洪水-nav2-navfn-如何把-costmap-变成路径" tabindex="-1">从机器人脚下掀起一场“势能洪水”：Nav2 NavFn 如何把 Costmap 变成路径？ <a class="header-anchor" href="#从机器人脚下掀起一场-势能洪水-nav2-navfn-如何把-costmap-变成路径" aria-label="Permalink to &quot;从机器人脚下掀起一场“势能洪水”：Nav2 NavFn 如何把 Costmap 变成路径？&quot;">​</a></h1><p>给 NavFn 一张 Costmap、一个机器人位置和一个目标点，它不会直接在栅格里保存一串父节点，也不会先得到折线路径再调用独立平滑器。</p><p>它真正做的是：把整张地图改写成一张导航势场，让势值从机器人所在栅格向外传播；目标附近一旦拥有有限势值，再从目标沿负势梯度走回机器人，最后把这段内部路径逆序，得到机器人到目标的 <code>nav_msgs/Path</code>。</p><p>这套实现里最容易看反的是 <code>start</code> 与 <code>goal</code>。ROS 请求的起点被写入 NavFn 的内部 <code>goal</code>，ROS 请求的目标反而被写入内部 <code>start</code>。只有先把这层变量语义理顺，Dijkstra、A*、目标容差和路径回溯才能连成同一条数据流。</p><p>本文基于当前本地 <code>navigation2</code>、<code>nav2_navfn_planner 1.1.20</code> 源码，只拆 Costmap 转换、势场传播、平面波更新、A*／Dijkstra、梯度取路和目标整形等核心算法。</p><p><img src="'+o+`" alt="NavFn 核心算法总数据流"></p><h2 id="一、navfn-求解的不是一串父节点" tabindex="-1">一、NavFn 求解的不是一串父节点 <a class="header-anchor" href="#一、navfn-求解的不是一串父节点" aria-label="Permalink to &quot;一、NavFn 求解的不是一串父节点&quot;">​</a></h2><h3 id="_1-1-输入最终落成三块核心数据" tabindex="-1">1.1 输入最终落成三块核心数据 <a class="header-anchor" href="#_1-1-输入最终落成三块核心数据" aria-label="Permalink to &quot;1.1 输入最终落成三块核心数据&quot;">​</a></h3><p><code>NavfnPlanner::makePlan()</code> 接收 ROS 世界坐标下的机器人起点 <code>start</code>、请求目标 <code>goal</code> 和目标容差 <code>tolerance</code>。真正进入算法内核的数据是：</p><ul><li>一维栅格通行代价数组 <code>costarr</code>。</li><li>一维导航势数组 <code>potarr</code>。</li><li>两个整数栅格坐标 <code>start[2]</code> 与 <code>goal[2]</code>。</li></ul><p>二维栅格 <code>(x, y)</code> 在数组中的索引为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>index = y * nx + x</span></span></code></pre></div><p><code>costarr[index]</code> 表示该格能否通过以及穿越有多贵，<code>potarr[index]</code> 表示从零势源走到该格需要积累多少导航势。</p><h3 id="_1-2-势值是到零势源的累计通行代价" tabindex="-1">1.2 势值是到零势源的累计通行代价 <a class="header-anchor" href="#_1-2-势值是到零势源的累计通行代价" aria-label="Permalink to &quot;1.2 势值是到零势源的累计通行代价&quot;">​</a></h3><p>每轮规划开始时，全部 <code>potarr</code> 被重置为 <code>POT_HIGH=1.0e10</code>。这个大数不是普通高代价，而是“势场尚未抵达”或“从当前传播域不可达”的哨兵值。</p><p>内部 <code>goal</code> 所在格被设为零势：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>potarr[goal] = 0</span></span></code></pre></div><p>随后波前不断更新四邻域。空旷区域每跨一格至少增加 <code>COST_NEUTRAL=50</code>，膨胀区与未知区增加得更多，障碍格完全不参与传播。因此，势场同时编码了距离和 Costmap 风险。</p><h3 id="_1-3-输出路径来自势场坡度" tabindex="-1">1.3 输出路径来自势场坡度 <a class="header-anchor" href="#_1-3-输出路径来自势场坡度" aria-label="Permalink to &quot;1.3 输出路径来自势场坡度&quot;">​</a></h3><p>当候选终点已经拥有有限势值，<code>calcPath()</code> 从该点出发，持续朝势值下降的方向移动。正常情况下它不只在栅格中心间跳转，而是对四个角点的梯度做双线性插值，每次前进 <code>0.5</code> 个栅格。</p><p>所以 NavFn 的路径比“只保存八邻域父节点并原样回溯”更连续，但这仍是势场插值结果，不等于带曲率约束的车辆轨迹，也不等于优化型路径平滑。</p><h3 id="_1-4-算法主链可以压缩成一行" tabindex="-1">1.4 算法主链可以压缩成一行 <a class="header-anchor" href="#_1-4-算法主链可以压缩成一行" aria-label="Permalink to &quot;1.4 算法主链可以压缩成一行&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Costmap</span></span>
<span class="line"><span>→ 内部通行代价</span></span>
<span class="line"><span>→ 零势源初始化</span></span>
<span class="line"><span>→ Dijkstra / A* 调度波前</span></span>
<span class="line"><span>→ 平面波更新 potarr</span></span>
<span class="line"><span>→ 选择有限势终点</span></span>
<span class="line"><span>→ 负势梯度取路</span></span>
<span class="line"><span>→ 逆序与坐标转换</span></span>
<span class="line"><span>→ nav_msgs/Path</span></span></code></pre></div><h2 id="二、costmap-不是原样进入势场" tabindex="-1">二、Costmap 不是原样进入势场 <a class="header-anchor" href="#二、costmap-不是原样进入势场" aria-label="Permalink to &quot;二、Costmap 不是原样进入势场&quot;">​</a></h2><p><img src="`+p+`" alt="Costmap 到 NavFn 内部代价的转换"></p><h3 id="_2-1-普通栅格先被抬高到中性代价" tabindex="-1">2.1 普通栅格先被抬高到中性代价 <a class="header-anchor" href="#_2-1-普通栅格先被抬高到中性代价" aria-label="Permalink to &quot;2.1 普通栅格先被抬高到中性代价&quot;">​</a></h3><p><code>setCostmap()</code> 按下面的线性关系转换 ROS Costmap 的 <code>0～252</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>navfn_cost = min(50 + 0.8 * costmap_cost, 253)</span></span></code></pre></div><p>这意味着 Costmap 自由空间 <code>0</code> 进入 NavFn 后不是零，而是 <code>50</code>。势值因而会随路径长度稳定增长，哪怕整段路径都处于完全自由空间。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Costmap 0    → NavFn 50</span></span>
<span class="line"><span>Costmap 100  → NavFn 130</span></span>
<span class="line"><span>Costmap 200  → NavFn 210</span></span>
<span class="line"><span>Costmap 252  → NavFn 251</span></span></code></pre></div><p>膨胀代价越高，势场的坡就越陡。路径沿负势梯度提取时，自然更偏向较低代价走廊。</p><h3 id="_2-2-致命障碍与内切障碍统一封死" tabindex="-1">2.2 致命障碍与内切障碍统一封死 <a class="header-anchor" href="#_2-2-致命障碍与内切障碍统一封死" aria-label="Permalink to &quot;2.2 致命障碍与内切障碍统一封死&quot;">​</a></h3><p>ROS Costmap 值 <code>253</code> 和 <code>254</code> 都被转换为内部 <code>COST_OBS=254</code>。所有入队宏和势值更新都要求：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>costarr[n] &lt; COST_OBS</span></span></code></pre></div><p>因此内部代价 <code>254</code> 是不可传播边界。波前只能绕开它，不能靠“支付更高代价”穿过去。</p><h3 id="_2-3-未知空间的语义由-allow-unknown-决定" tabindex="-1">2.3 未知空间的语义由 allow_unknown 决定 <a class="header-anchor" href="#_2-3-未知空间的语义由-allow-unknown-决定" aria-label="Permalink to &quot;2.3 未知空间的语义由 allow_unknown 决定&quot;">​</a></h3><p>Costmap 的未知值为 <code>255</code>。当 <code>allow_unknown=true</code> 时，它被转换为内部 <code>253</code>；当 <code>allow_unknown=false</code> 时，它被转换为 <code>254</code>。</p><p>这个差异只有一个数值，却改变了拓扑：</p><ul><li>内部 <code>253 &lt; 254</code>，波前可以穿过未知格，但每格代价极高。</li><li>内部 <code>254</code>，未知格与障碍一样，波前不能进入。</li></ul><p>所以“允许未知空间”不等于把未知区域当成自由空间，而是把它当成可穿越的高代价区域。</p><h3 id="_2-4-地图最外圈会被二次封边" tabindex="-1">2.4 地图最外圈会被二次封边 <a class="header-anchor" href="#_2-4-地图最外圈会被二次封边" aria-label="Permalink to &quot;2.4 地图最外圈会被二次封边&quot;">​</a></h3><p><code>setupNavFn()</code> 不信任输入地图的边缘状态。每次传播前，它都会把首行、末行、首列和末列强制写成 <code>COST_OBS</code>。</p><p>这既避免了无边界检查的四邻域访问越界，也意味着贴着 Costmap 最外圈的通道会被 NavFn 主动封闭。调试“地图边缘明明是自由空间却无法规划”时，不能只看原始 Costmap。</p><h2 id="三、包装层交换了内部-start-与-goal" tabindex="-1">三、包装层交换了内部 start 与 goal <a class="header-anchor" href="#三、包装层交换了内部-start-与-goal" aria-label="Permalink to &quot;三、包装层交换了内部 start 与 goal&quot;">​</a></h2><p><img src="`+i+`" alt="NavFn 内部变量与真实传播方向"></p><h3 id="_3-1-ros-起点被写入内部-goal" tabindex="-1">3.1 ROS 起点被写入内部 goal <a class="header-anchor" href="#_3-1-ros-起点被写入内部-goal" aria-label="Permalink to &quot;3.1 ROS 起点被写入内部 goal&quot;">​</a></h3><p>机器人世界坐标先经 <code>worldToMap()</code> 变成 <code>map_start</code>。目标点变成 <code>map_goal</code>。随后源码执行：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">planner_-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setStart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(map_goal);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">planner_-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setGoal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(map_start);</span></span></code></pre></div><p>对应关系是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NavFn start = ROS 请求目标</span></span>
<span class="line"><span>NavFn goal  = ROS 机器人起点</span></span></code></pre></div><p>这不是注释笔误，而是后续势场、容差和路径方向的基础。</p><h3 id="_3-2-势场从机器人位置向请求目标传播" tabindex="-1">3.2 势场从机器人位置向请求目标传播 <a class="header-anchor" href="#_3-2-势场从机器人位置向请求目标传播" aria-label="Permalink to &quot;3.2 势场从机器人位置向请求目标传播&quot;">​</a></h3><p><code>setupNavFn()</code> 总是把内部 <code>goal</code> 的势设为零，并把它的四个邻格送入当前优先级缓冲区。因为内部 <code>goal</code> 就是 ROS 起点，真实波前方向为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>机器人位置 → 请求目标</span></span></code></pre></div><p>Dijkstra 的 <code>atStart=true</code> 和 A* 的终止判断都检查内部 <code>start</code> 是否获得有限势。换回 ROS 语义，就是检查请求目标是否已经被机器人起点发出的势场抵达。</p><h3 id="_3-3-交换让目标容差检查变得直接" tabindex="-1">3.3 交换让目标容差检查变得直接 <a class="header-anchor" href="#_3-3-交换让目标容差检查变得直接" aria-label="Permalink to &quot;3.3 交换让目标容差检查变得直接&quot;">​</a></h3><p>请求目标可能恰好落在障碍、膨胀致命区或不可达孤岛中。包装层需要在目标附近寻找一个可达候选点。</p><p>由于势场以机器人位置为零势源，任意栅格的 <code>potarr</code> 都直接回答：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>机器人能否从当前起点到达这个栅格？</span></span></code></pre></div><p>因此候选终点只需检查 <code>potential &lt; POT_HIGH</code>，不必为每个候选重新运行一次搜索。</p><h3 id="_3-4-内部路径方向必须再次翻转" tabindex="-1">3.4 内部路径方向必须再次翻转 <a class="header-anchor" href="#_3-4-内部路径方向必须再次翻转" aria-label="Permalink to &quot;3.4 内部路径方向必须再次翻转&quot;">​</a></h3><p><code>calcPath()</code> 默认从内部 <code>start</code> 开始，也就是从请求目标或容差候选点开始，沿负势梯度走向内部 <code>goal</code>，也就是机器人位置。</p><p>得到的 <code>pathx</code>／<code>pathy</code> 顺序为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>候选终点 → 机器人起点</span></span></code></pre></div><p><code>getPlanFromPotential()</code> 从 <code>len-1</code> 递减到 <code>0</code> 读取数组，才恢复成 ROS 消费方需要的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>机器人起点 → 候选终点</span></span></code></pre></div><h2 id="四、波前不是普通队列-而是三组势值桶" tabindex="-1">四、波前不是普通队列，而是三组势值桶 <a class="header-anchor" href="#四、波前不是普通队列-而是三组势值桶" aria-label="Permalink to &quot;四、波前不是普通队列，而是三组势值桶&quot;">​</a></h2><h3 id="_4-1-三块固定数组承担优先级调度" tabindex="-1">4.1 三块固定数组承担优先级调度 <a class="header-anchor" href="#_4-1-三块固定数组承担优先级调度" aria-label="Permalink to &quot;4.1 三块固定数组承担优先级调度&quot;">​</a></h3><p>NavFn 没有使用 <code>std::priority_queue</code>。它预先分配三块长度均为 <code>PRIORITYBUFSIZE=10000</code> 的整数数组：</p><ul><li><code>curP</code> 保存当前阈值下正在处理的栅格。</li><li><code>nextP</code> 保存本批更新产生的低势候选。</li><li><code>overP</code> 保存超过当前阈值的候选。</li></ul><p><code>pending[]</code> 记录栅格是否已经等待处理，避免同一格在一次调度阶段被重复插入。</p><h3 id="_4-2-势阈值按固定增量上升" tabindex="-1">4.2 势阈值按固定增量上升 <a class="header-anchor" href="#_4-2-势阈值按固定增量上升" aria-label="Permalink to &quot;4.2 势阈值按固定增量上升&quot;">​</a></h3><p>初始阈值为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>curT = COST_OBS = 254</span></span></code></pre></div><p>阈值增量为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>priInc = 2 * COST_NEUTRAL = 100</span></span></code></pre></div><p>新势值低于 <code>curT</code> 时，受影响邻格进入 <code>nextP</code>；否则进入 <code>overP</code>。当前与下一缓冲都耗尽后，<code>curT</code> 增加 <code>100</code>，原来的溢出缓冲成为新的当前缓冲。</p><p>这是一种粗粒度桶式优先队列：势更低的区域优先推进，势更高的区域被延后，但不用维护逐元素堆结构。</p><h3 id="_4-3-四邻域传播带着近似对角门槛" tabindex="-1">4.3 四邻域传播带着近似对角门槛 <a class="header-anchor" href="#_4-3-四邻域传播带着近似对角门槛" aria-label="Permalink to &quot;4.3 四邻域传播带着近似对角门槛&quot;">​</a></h3><p>中心格势值降低后，源码检查左、右、上、下四个邻格是否值得重新入队。比较中加入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0.707106781 * neighbor_cost</span></span></code></pre></div><p>这个 <code>1/√2</code> 系数不是让搜索直接扩展对角邻居，而是作为邻格受当前新势影响的调度门槛。真正的传播和势值读取仍建立在四邻域上。</p><h3 id="_4-4-固定容量是必须知道的工程边界" tabindex="-1">4.4 固定容量是必须知道的工程边界 <a class="header-anchor" href="#_4-4-固定容量是必须知道的工程边界" aria-label="Permalink to &quot;4.4 固定容量是必须知道的工程边界&quot;">​</a></h3><p>三个入队宏都带有：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>buffer_count &lt; 10000</span></span></code></pre></div><p>缓冲区满时，新的候选不会插入，源码也不会扩容或抛出错误。普通尺寸地图和常见波前通常不会触发，但在超大地图、复杂等势前沿或异常高并发候选场景中，这个静默容量上限值得纳入失败排查。</p><h2 id="五、一个栅格的势值如何计算" tabindex="-1">五、一个栅格的势值如何计算 <a class="header-anchor" href="#五、一个栅格的势值如何计算" aria-label="Permalink to &quot;五、一个栅格的势值如何计算&quot;">​</a></h2><p><img src="`+l+`" alt="NavFn 平面波更新与桶式传播"></p><h3 id="_5-1-横纵方向各取一个最低势邻居" tabindex="-1">5.1 横纵方向各取一个最低势邻居 <a class="header-anchor" href="#_5-1-横纵方向各取一个最低势邻居" aria-label="Permalink to &quot;5.1 横纵方向各取一个最低势邻居&quot;">​</a></h3><p>对待更新栅格 <code>n</code>，先读取四邻域势值：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>l = potarr[n - 1]</span></span>
<span class="line"><span>r = potarr[n + 1]</span></span>
<span class="line"><span>u = potarr[n - nx]</span></span>
<span class="line"><span>d = potarr[n + nx]</span></span></code></pre></div><p>再分别取横向和纵向的较小值：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tc = min(l, r)</span></span>
<span class="line"><span>ta = min(u, d)</span></span></code></pre></div><p>源码通过交换保证 <code>ta &lt;= tc</code>，并定义：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hf = costarr[n]</span></span>
<span class="line"><span>dc = tc - ta</span></span></code></pre></div><p><code>hf</code> 是穿越当前格的代价，<code>dc</code> 是两个有效方向的势差。</p><h3 id="_5-2-势差大时退化为单邻居更新" tabindex="-1">5.2 势差大时退化为单邻居更新 <a class="header-anchor" href="#_5-2-势差大时退化为单邻居更新" aria-label="Permalink to &quot;5.2 势差大时退化为单邻居更新&quot;">​</a></h3><p>当：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dc &gt;= hf</span></span></code></pre></div><p>较高势邻居提供的信息太弱，新势值只依赖最低势邻居：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pot = ta + hf</span></span></code></pre></div><p>这与常见最短路更新直觉一致：从已知最便宜的相邻格跨入当前格，并支付当前格代价。</p><h3 id="_5-3-势差小时使用二邻居平面波近似" tabindex="-1">5.3 势差小时使用二邻居平面波近似 <a class="header-anchor" href="#_5-3-势差小时使用二邻居平面波近似" aria-label="Permalink to &quot;5.3 势差小时使用二邻居平面波近似&quot;">​</a></h3><p>当：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dc &lt; hf</span></span></code></pre></div><p>横纵两个方向都对波面形状有贡献。NavFn 使用一个二次多项式近似：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d = dc / hf</span></span>
<span class="line"><span>v = -0.2301 * d² + 0.5307 * d + 0.7040</span></span>
<span class="line"><span>pot = ta + hf * v</span></span></code></pre></div><p>当两个方向势值接近时，波面可以从二维方向共同抵达当前格，新增势值会小于简单的 <code>ta + hf</code>。这也是 NavFn 能形成更连续势场，而不是纯曼哈顿距离层纹的关键。</p><h3 id="_5-4-只有更低的新势才会触发传播" tabindex="-1">5.4 只有更低的新势才会触发传播 <a class="header-anchor" href="#_5-4-只有更低的新势才会触发传播" aria-label="Permalink to &quot;5.4 只有更低的新势才会触发传播&quot;">​</a></h3><p>新势计算完后仍需满足：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pot &lt; potarr[n]</span></span></code></pre></div><p>只有势值得到改善，才写回 <code>potarr[n]</code> 并检查周围邻格。势场因此不断做松弛，直到请求目标被抵达、队列耗尽或达到最大循环数。</p><h2 id="六、dijkstra-与-a-共享同一张势场公式" tabindex="-1">六、Dijkstra 与 A* 共享同一张势场公式 <a class="header-anchor" href="#六、dijkstra-与-a-共享同一张势场公式" aria-label="Permalink to &quot;六、Dijkstra 与 A* 共享同一张势场公式&quot;">​</a></h2><p><img src="`+c+`" alt="NavFn Dijkstra 与 A* 的真正差异"></p><h3 id="_6-1-dijkstra-直接按累计势调度" tabindex="-1">6.1 Dijkstra 直接按累计势调度 <a class="header-anchor" href="#_6-1-dijkstra-直接按累计势调度" aria-label="Permalink to &quot;6.1 Dijkstra 直接按累计势调度&quot;">​</a></h3><p><code>updateCell()</code> 计算出原始 <code>pot</code> 后，直接用它与当前阈值 <code>curT</code> 比较：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>priority = pot</span></span></code></pre></div><p>没有目标方向启发项时，低势波前会从机器人位置较均匀地向外扩散。只要 <code>atStart=true</code>，请求目标一获得有限势，传播就停止。</p><h3 id="_6-2-a-只给调度优先级添加启发项" tabindex="-1">6.2 A* 只给调度优先级添加启发项 <a class="header-anchor" href="#_6-2-a-只给调度优先级添加启发项" aria-label="Permalink to &quot;6.2 A* 只给调度优先级添加启发项&quot;">​</a></h3><p><code>updateCellAstar()</code> 使用完全相同的平面波公式计算原始势值，然后求当前格到内部 <code>start</code> 的欧氏距离：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>h = hypot(x - start_x, y - start_y) * COST_NEUTRAL</span></span>
<span class="line"><span>priority = pot + h</span></span></code></pre></div><p>内部 <code>start</code> 是 ROS 请求目标，所以这个启发项把波前优先引向请求目标。</p><h3 id="_6-3-启发项不会污染-potarr" tabindex="-1">6.3 启发项不会污染 potarr <a class="header-anchor" href="#_6-3-启发项不会污染-potarr" aria-label="Permalink to &quot;6.3 启发项不会污染 potarr&quot;">​</a></h3><p>A* 源码的写入顺序非常重要：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">potarr[n] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dist;</span></span></code></pre></div><p><code>potarr</code> 保存的仍是未加启发项的导航势，<code>dist</code> 只临时用于决定邻格进入 <code>nextP</code> 还是 <code>overP</code>。</p><p>因此 Dijkstra 和 A* 产生的是同一类“通行累计势”，后续目标容差判断和负势梯度取路不需要知道启发项。二者主要区别是哪些栅格先被计算、通常访问多少栅格，而不是使用两套路径代价公式。</p><h3 id="_6-4-a-的初始阈值也向目标倾斜" tabindex="-1">6.4 A* 的初始阈值也向目标倾斜 <a class="header-anchor" href="#_6-4-a-的初始阈值也向目标倾斜" aria-label="Permalink to &quot;6.4 A* 的初始阈值也向目标倾斜&quot;">​</a></h3><p>A* 传播开始前，还会把机器人位置与请求目标的欧氏距离乘以 <code>50</code>，加到初始 <code>curT</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>curT = 254 + distance(start, goal) * 50</span></span></code></pre></div><p>后续每个栅格再以 <code>pot+h</code> 参与桶式调度。它不是标准二叉堆版本的逐节点 A*，而是“平面波势场＋启发式桶调度”的 NavFn 实现。</p><h3 id="_6-5-当前工程默认选择-a-配置组" tabindex="-1">6.5 当前工程默认选择 A* 配置组 <a class="header-anchor" href="#_6-5-当前工程默认选择-a-配置组" aria-label="Permalink to &quot;6.5 当前工程默认选择 A* 配置组&quot;">​</a></h3><p>当前 <code>nav2_regulated_modules</code> 与 <code>myagv_test_bringup</code> 都保留两套 NavFn 插件配置：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">GridBased</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tolerance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  use_astar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allow_unknown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">GridBasedAstar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tolerance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  use_astar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allow_unknown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>当前 <code>selected_planner</code> 为 <code>GridBasedAstar</code>。也就是说，实际默认路径使用 A* 调度，但仍走 NavFn 的代价转换、平面波势场和梯度取路。</p><h2 id="七、目标不可达时不会立刻失败" tabindex="-1">七、目标不可达时不会立刻失败 <a class="header-anchor" href="#七、目标不可达时不会立刻失败" aria-label="Permalink to &quot;七、目标不可达时不会立刻失败&quot;">​</a></h2><h3 id="_7-1-请求目标先接受精确势值检查" tabindex="-1">7.1 请求目标先接受精确势值检查 <a class="header-anchor" href="#_7-1-请求目标先接受精确势值检查" aria-label="Permalink to &quot;7.1 请求目标先接受精确势值检查&quot;">​</a></h3><p>势场传播结束后，包装层先读取请求目标对应的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>potential = potarr[goal_cell]</span></span></code></pre></div><p>只要它小于 <code>POT_HIGH</code>，就直接把请求目标作为路径提取起点。</p><p>这里不要求目标势“足够低”。有限势只表示从机器人起点出发的传播已经抵达该格。</p><h3 id="_7-2-tolerance-遍历的是正方形区域" tabindex="-1">7.2 tolerance 遍历的是正方形区域 <a class="header-anchor" href="#_7-2-tolerance-遍历的是正方形区域" aria-label="Permalink to &quot;7.2 tolerance 遍历的是正方形区域&quot;">​</a></h3><p>请求目标势为 <code>POT_HIGH</code> 时，源码以 Costmap 分辨率为步长，遍历：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x ∈ [goal.x - tolerance, goal.x + tolerance]</span></span>
<span class="line"><span>y ∈ [goal.y - tolerance, goal.y + tolerance]</span></span></code></pre></div><p>这是轴对齐正方形，不是严格的圆形半径。正方形角点也会被检查。</p><h3 id="_7-3-候选排序按几何距离而不是势值" tabindex="-1">7.3 候选排序按几何距离而不是势值 <a class="header-anchor" href="#_7-3-候选排序按几何距离而不是势值" aria-label="Permalink to &quot;7.3 候选排序按几何距离而不是势值&quot;">​</a></h3><p>每个候选先通过 <code>potential &lt; POT_HIGH</code> 判断可达，再计算它与原请求目标的欧氏距离平方：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sdist = (x - goal.x)² + (y - goal.y)²</span></span></code></pre></div><p>最终选取距离原目标最近的可达点，而不是选择势值最低、路径总代价最小或离机器人最近的点。</p><p>因此 <code>tolerance=0.5</code> 的真实含义是“目标失效时允许在周围网格中找最近可达替代终点”，不是给所有规划结果增加半米误差。</p><h3 id="_7-4-容差无法修复传播拓扑断裂" tabindex="-1">7.4 容差无法修复传播拓扑断裂 <a class="header-anchor" href="#_7-4-容差无法修复传播拓扑断裂" aria-label="Permalink to &quot;7.4 容差无法修复传播拓扑断裂&quot;">​</a></h3><p>容差候选必须已经拥有有限势。如果机器人和整个目标容差区域被障碍完全分隔，所有候选仍是 <code>POT_HIGH</code>，规划结果就是空 Path。</p><p>容差擅长处理目标落在障碍边缘、栅格离散误差或末端局部不可达，不会让算法穿墙，也不会跨越未允许的未知区域。</p><h2 id="八、负势梯度把候选终点拉回机器人" tabindex="-1">八、负势梯度把候选终点拉回机器人 <a class="header-anchor" href="#八、负势梯度把候选终点拉回机器人" aria-label="Permalink to &quot;八、负势梯度把候选终点拉回机器人&quot;">​</a></h2><p><img src="`+d+`" alt="目标容差、梯度取路与 ROS Path 输出"></p><h3 id="_8-1-calcpath-从候选终点开始" tabindex="-1">8.1 calcPath 从候选终点开始 <a class="header-anchor" href="#_8-1-calcpath-从候选终点开始" aria-label="Permalink to &quot;8.1 calcPath 从候选终点开始&quot;">​</a></h3><p>包装层先把内部 <code>start</code> 更新为选中的 <code>best_pose</code>，再调用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>calcPath(max(nx, ny) * 4)</span></span></code></pre></div><p>路径缓存起点是候选终点。内部终点仍是零势的机器人位置。</p><p>每轮循环先保存当前亚栅格坐标，再尝试沿势值降低方向前进。只要当前位置附近的势小于 <code>COST_NEUTRAL=50</code>，算法就直接追加内部 <code>goal</code>，完成内部方向的候选终点到机器人路径。</p><h3 id="_8-2-gradcell-计算归一化负势梯度" tabindex="-1">8.2 gradCell 计算归一化负势梯度 <a class="header-anchor" href="#_8-2-gradcell-计算归一化负势梯度" aria-label="Permalink to &quot;8.2 gradCell 计算归一化负势梯度&quot;">​</a></h3><p>普通可达栅格的梯度近似来自左右、上下势差：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dx += pot(left) - pot(center)</span></span>
<span class="line"><span>dx += pot(center) - pot(right)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>dy += pot(up) - pot(center)</span></span>
<span class="line"><span>dy += pot(center) - pot(down)</span></span></code></pre></div><p>随后用 <code>hypot(dx, dy)</code> 归一化。正方向对应数组中的右和下，向量整体指向势值更低的方向。</p><p>梯度被缓存在 <code>gradx</code>／<code>grady</code> 中，已经计算过的栅格可以复用。</p><h3 id="_8-3-四角梯度经过双线性插值" tabindex="-1">8.3 四角梯度经过双线性插值 <a class="header-anchor" href="#_8-3-四角梯度经过双线性插值" aria-label="Permalink to &quot;8.3 四角梯度经过双线性插值&quot;">​</a></h3><p>路径点不总在栅格中心。源码用当前整数格和右、下、右下四个角点的梯度，先沿 <code>x</code> 插值，再沿 <code>y</code> 插值：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gx = bilinear(gradx, dx, dy)</span></span>
<span class="line"><span>gy = bilinear(grady, dx, dy)</span></span></code></pre></div><p>然后把插值向量缩放到固定步长：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>step_scale = 0.5 / hypot(gx, gy)</span></span>
<span class="line"><span>offset += gradient * step_scale</span></span></code></pre></div><p>偏移超过一个栅格时，再修正整数索引和局部偏移。这样得到的内部路径可以穿过亚栅格位置，而不是只能连接栅格中心。</p><h3 id="_8-4-高势边界会切换为八邻域跟随" tabindex="-1">8.4 高势边界会切换为八邻域跟随 <a class="header-anchor" href="#_8-4-高势边界会切换为八邻域跟随" aria-label="Permalink to &quot;8.4 高势边界会切换为八邻域跟随&quot;">​</a></h3><p>如果当前格周围九个位置中存在 <code>POT_HIGH</code>，连续梯度可能不稳定。源码会暂停双线性插值，检查周围八邻格，直接移动到势值最低的格子，并把亚栅格偏移清零。</p><p>这个分支也用于修复路径在两个位置之间来回振荡的情况。源码通过比较当前路径点与前两个路径点，检测二周期振荡。</p><h3 id="_8-5-零梯度和超长路径都会失败" tabindex="-1">8.5 零梯度和超长路径都会失败 <a class="header-anchor" href="#_8-5-零梯度和超长路径都会失败" aria-label="Permalink to &quot;8.5 零梯度和超长路径都会失败&quot;">​</a></h3><p>以下情况会让 <code>calcPath()</code> 返回 <code>0</code>：</p><ul><li>当前索引接近数组边界，继续插值可能越界。</li><li>八邻域最低势仍为 <code>POT_HIGH</code>。</li><li>插值后的 <code>x</code>、<code>y</code> 梯度同时为零。</li><li>在允许循环数内没有抵达零势区域。</li></ul><p>包装层即使找到了有限势候选，也会在路径提取失败时输出错误并返回空 Path。</p><h2 id="九、离散路径还要经过两次末端整形" tabindex="-1">九、离散路径还要经过两次末端整形 <a class="header-anchor" href="#九、离散路径还要经过两次末端整形" aria-label="Permalink to &quot;九、离散路径还要经过两次末端整形&quot;">​</a></h2><h3 id="_9-1-包装层把内部路径逆序并换回世界坐标" tabindex="-1">9.1 包装层把内部路径逆序并换回世界坐标 <a class="header-anchor" href="#_9-1-包装层把内部路径逆序并换回世界坐标" aria-label="Permalink to &quot;9.1 包装层把内部路径逆序并换回世界坐标&quot;">​</a></h3><p><code>pathx</code>／<code>pathy</code> 是候选终点到机器人位置的栅格坐标。包装层从数组尾部向头部遍历，并执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>world_x = origin_x + map_x * resolution</span></span>
<span class="line"><span>world_y = origin_y + map_y * resolution</span></span></code></pre></div><p>输出 Pose 的初始方向统一为单位四元数，对应零偏航。最终 Path 顺序成为机器人位置到候选终点。</p><h3 id="_9-2-smoothapproachtogoal-只处理最后一个点" tabindex="-1">9.2 smoothApproachToGoal 只处理最后一个点 <a class="header-anchor" href="#_9-2-smoothapproachtogoal-只处理最后一个点" aria-label="Permalink to &quot;9.2 smoothApproachToGoal 只处理最后一个点&quot;">​</a></h3><p><code>smoothApproachToGoal()</code> 的名字容易让人误解。它不是遍历整条路径的平滑器，只比较：</p><ul><li>Path 尾部前一 Pose 到当前最后 Pose 的距离。</li><li>Path 尾部前一 Pose 到真实候选终点的距离。</li></ul><p>如果真实候选终点更近，就用它替换最后点；否则把真实候选终点追加到 Path 尾部。它修复的是离散取路末端的小折返或缺口，不会重塑整条路径。</p><h3 id="_9-3-最终方向默认保留候选目标姿态" tabindex="-1">9.3 最终方向默认保留候选目标姿态 <a class="header-anchor" href="#_9-3-最终方向默认保留候选目标姿态" aria-label="Permalink to &quot;9.3 最终方向默认保留候选目标姿态&quot;">​</a></h3><p>当前 NavFn 配置没有显式设置 <code>use_final_approach_orientation</code>，使用默认值 <code>false</code>。在这种模式下，末端 Pose 由 <code>best_pose</code> 带入的目标姿态决定。</p><p>若启用 <code>use_final_approach_orientation=true</code>，包装层会用末点与前一个有效点的连线方向设置末端朝向，让机器人保持最后接近方向，而不是强制旋转到请求目标姿态。</p><h3 id="_9-4-起终点重合走独立短路" tabindex="-1">9.4 起终点重合走独立短路 <a class="header-anchor" href="#_9-4-起终点重合走独立短路" aria-label="Permalink to &quot;9.4 起终点重合走独立短路&quot;">​</a></h3><p>当起点和目标的 <code>x、y</code> 完全相等，算法不会建立势场。如果该格不是致命障碍，直接输出只含一个 Pose 的 Path。</p><p>默认方向使用请求目标方向；启用最终接近方向模式时保留起点方向，避免局部控制器只为方向差驱动机器人原地旋转。</p><h2 id="十、四个参数改变的是不同算法边界" tabindex="-1">十、四个参数改变的是不同算法边界 <a class="header-anchor" href="#十、四个参数改变的是不同算法边界" aria-label="Permalink to &quot;十、四个参数改变的是不同算法边界&quot;">​</a></h2><h3 id="_10-1-tolerance-只在精确目标不可达时生效" tabindex="-1">10.1 tolerance 只在精确目标不可达时生效 <a class="header-anchor" href="#_10-1-tolerance-只在精确目标不可达时生效" aria-label="Permalink to &quot;10.1 tolerance 只在精确目标不可达时生效&quot;">​</a></h3><p>请求目标势有限时，<code>tolerance</code> 不参与路径选择。只有目标势为 <code>POT_HIGH</code>，才扫描目标附近候选。</p><p>增大它会扩大可接受终点区域，也可能让机器人停在离请求目标更远的位置。它不是解决整图不可达的搜索半径。</p><h3 id="_10-2-use-astar-只切换波前调度" tabindex="-1">10.2 use_astar 只切换波前调度 <a class="header-anchor" href="#_10-2-use-astar-只切换波前调度" aria-label="Permalink to &quot;10.2 use_astar 只切换波前调度&quot;">​</a></h3><p><code>use_astar=false</code> 调用 <code>calcNavFnDijkstra(true)</code>，<code>use_astar=true</code> 调用 <code>calcNavFnAstar()</code>。</p><p>它不会更换代价映射、平面波公式或路径提取器。比较两种模式时，应重点观察访问栅格量、规划耗时和桶式调度效果，而不是假设 A* 会启用一套全新轨迹平滑算法。</p><h3 id="_10-3-allow-unknown-改变未知区是否属于可行域" tabindex="-1">10.3 allow_unknown 改变未知区是否属于可行域 <a class="header-anchor" href="#_10-3-allow-unknown-改变未知区是否属于可行域" aria-label="Permalink to &quot;10.3 allow_unknown 改变未知区是否属于可行域&quot;">​</a></h3><p><code>allow_unknown=true</code> 把未知格转换成可传播的 <code>253</code>；关闭后转换成不可传播的 <code>254</code>。</p><p>在探索型地图里开启它可以让规划穿过未观测区，但路径仍会受到极高单格代价影响。在已知静态地图或安全边界严格的场景中，关闭它能阻止规划进入未知区域。</p><h3 id="_10-4-use-final-approach-orientation-只改最后-pose" tabindex="-1">10.4 use_final_approach_orientation 只改最后 Pose <a class="header-anchor" href="#_10-4-use-final-approach-orientation-只改最后-pose" aria-label="Permalink to &quot;10.4 use_final_approach_orientation 只改最后 Pose&quot;">​</a></h3><p>这个参数不参与势场、候选终点或路径坐标计算，只决定最终 Path 尾部 Pose 的朝向。</p><p>若后续 Controller 或 GoalChecker 强依赖目标姿态，使用目标原姿态更直接；若不希望机器人在路径末端额外旋转，最终接近方向更合适。</p><h2 id="十一、源码里还有几条容易漏掉的边界" tabindex="-1">十一、源码里还有几条容易漏掉的边界 <a class="header-anchor" href="#十一、源码里还有几条容易漏掉的边界" aria-label="Permalink to &quot;十一、源码里还有几条容易漏掉的边界&quot;">​</a></h2><h3 id="_11-1-起点清障会写回原-costmap" tabindex="-1">11.1 起点清障会写回原 Costmap <a class="header-anchor" href="#_11-1-起点清障会写回原-costmap" aria-label="Permalink to &quot;11.1 起点清障会写回原 Costmap&quot;">​</a></h3><p>包装层认为机器人当前所在格不应是障碍，因此调用：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">costmap_-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setCost</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mx, my, FREE_SPACE);</span></span></code></pre></div><p>这不是只修改 NavFn 的内部副本，而是直接修改原 Costmap。并且该调用发生在获取 Costmap mutex 之前。它有利于处理机器人 footprint 把自身起点标成障碍的情况，但并非纯只读规划。</p><h3 id="_11-2-坐标转换使用-round-而不是-floor" tabindex="-1">11.2 坐标转换使用 round 而不是 floor <a class="header-anchor" href="#_11-2-坐标转换使用-round-而不是-floor" aria-label="Permalink to &quot;11.2 坐标转换使用 round 而不是 floor&quot;">​</a></h3><p><code>worldToMap()</code> 使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>round((world - origin) / resolution)</span></span></code></pre></div><p><code>mapToWorld()</code> 则直接使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>origin + map * resolution</span></span></code></pre></div><p>它没有补 <code>0.5 * resolution</code> 的栅格中心偏移。分析末端半栅格误差或与其他 Costmap 坐标工具差异时，要以这组本地实现为准。</p><h3 id="_11-3-dijkstra-的调试-path-cost-不可靠" tabindex="-1">11.3 Dijkstra 的调试 path cost 不可靠 <a class="header-anchor" href="#_11-3-dijkstra-的调试-path-cost-不可靠" aria-label="Permalink to &quot;11.3 Dijkstra 的调试 path cost 不可靠&quot;">​</a></h3><p><code>last_path_cost_</code> 只在 <code>propNavFnAstar()</code> 结束时被赋值。Dijkstra 传播没有更新它，但路径提取后仍统一调用 <code>getLastPathCost()</code> 输出 debug 日志。</p><p>因此 Dijkstra 模式下日志中的该 cost 不应被当成可靠路径代价指标。Path 是否成功仍由势场、<code>calcPath()</code> 返回值和输出 Pose 数量决定。</p><h3 id="_11-4-最大传播与取路次数都有限" tabindex="-1">11.4 最大传播与取路次数都有限 <a class="header-anchor" href="#_11-4-最大传播与取路次数都有限" aria-label="Permalink to &quot;11.4 最大传播与取路次数都有限&quot;">​</a></h3><p>势场传播循环上限为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>max(nx * ny / 20, nx + ny)</span></span></code></pre></div><p>路径提取循环上限为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>max(nx, ny) * 4</span></span></code></pre></div><p>NavFn 不是无界运行。极端曲折通道、超大地图或异常势场既可能耗尽传播轮数，也可能让路径长度超过取路上限。</p><h3 id="_11-5-运行路径集中在两份源文件和一份头文件" tabindex="-1">11.5 运行路径集中在两份源文件和一份头文件 <a class="header-anchor" href="#_11-5-运行路径集中在两份源文件和一份头文件" aria-label="Permalink to &quot;11.5 运行路径集中在两份源文件和一份头文件&quot;">​</a></h3><p>核心算法可沿以下边界阅读：</p><ul><li><code>src/navfn_planner.cpp</code>：ROS 坐标、Costmap、起终点交换、目标容差、逆序输出和末端方向。</li><li><code>src/navfn.cpp</code>：内部代价、三缓冲传播、平面波势值、A* 启发项、梯度与路径提取。</li><li><code>include/nav2_navfn_planner/navfn.hpp</code>：常量、数组和内部状态定义。</li></ul><p>源码中的 <code>create_nav_plan_astar()</code> 位于整段注释中，不属于当前插件运行链。</p><h2 id="十二、看懂-navfn-的关键是把三种方向分开" tabindex="-1">十二、看懂 NavFn 的关键是把三种方向分开 <a class="header-anchor" href="#十二、看懂-navfn-的关键是把三种方向分开" aria-label="Permalink to &quot;十二、看懂 NavFn 的关键是把三种方向分开&quot;">​</a></h2><h3 id="_12-1-势场方向是机器人到目标" tabindex="-1">12.1 势场方向是机器人到目标 <a class="header-anchor" href="#_12-1-势场方向是机器人到目标" aria-label="Permalink to &quot;12.1 势场方向是机器人到目标&quot;">​</a></h3><p>包装层把 ROS 起点写成内部 <code>goal</code>，零势由机器人位置向外传播。当前默认 A* 再用到请求目标的欧氏距离，引导波前更快抵达目标。</p><h3 id="_12-2-内部取路方向是目标到机器人" tabindex="-1">12.2 内部取路方向是目标到机器人 <a class="header-anchor" href="#_12-2-内部取路方向是目标到机器人" aria-label="Permalink to &quot;12.2 内部取路方向是目标到机器人&quot;">​</a></h3><p>目标或容差候选点从高势处出发，沿负势梯度下降，最终抵达机器人所在的零势位置。双线性梯度插值让这条内部路径具备亚栅格连续性。</p><h3 id="_12-3-对外-path-方向重新变成机器人到目标" tabindex="-1">12.3 对外 Path 方向重新变成机器人到目标 <a class="header-anchor" href="#_12-3-对外-path-方向重新变成机器人到目标" aria-label="Permalink to &quot;12.3 对外 Path 方向重新变成机器人到目标&quot;">​</a></h3><p>包装层把内部路径逆序，转换到世界坐标，修整最后离散点和末端方向，才生成 Controller Server、Smoother Server 与控制器能够消费的 <code>nav_msgs/Path</code>。</p><p>NavFn 的精髓不是“用了 Dijkstra 还是 A*”这一行开关，而是同一套连续链路：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Costmap 风险</span></span>
<span class="line"><span>→ 平面波导航势</span></span>
<span class="line"><span>→ 启发式波前调度</span></span>
<span class="line"><span>→ 负势梯度</span></span>
<span class="line"><span>→ 亚栅格路径</span></span></code></pre></div><p>一张离散代价地图，正是在这条链路中长成了一条可以交给机器人执行的全局路径。</p>`,241)])])}const x=e(r,[["render",h]]);export{_ as __pageData,x as default};
